"""Smart Parking Assist (Ultrasonic + OLED + Buzzer + RGB LED)"""
from espzero import DistanceSensor, Buzzer, OLED, esp_led
from time import sleep

ds = DistanceSensor(echo=14, trigger=13)
buzzer = Buzzer(15)
oled = OLED(scl=47, sda=21)

while True:
    dist = ds.distance  # cm
    if dist < 10:
        oled.show_face("angry")
        esp_led.color = "red"
        buzzer.beep(0.05, 0.05, n=1)
    elif dist < 25:
        oled.show_face("surprised")
        esp_led.color = "yellow"
        buzzer.beep(0.15, 0.15, n=1)
    else:
        oled.show_face("happy")
        esp_led.color = "green"
    sleep(0.2)
